import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv2d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#define TILE_H 16
#define TILE_W 16
#define UNROLL_H 2
#define UNROLL_W 4
#define OUT_TILE_H (TILE_H * UNROLL_H)
#define OUT_TILE_W (TILE_W * UNROLL_W)
#define COUT_TILE 4
__global__ void conv2d_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    float* __restrict__ out,
    int N, int Cin, int H, int W,
    int Cout, int KH, int KW,
    int strideH, int strideW,
    int padH, int padW,
    int dilH, int dilW,
    int Hout, int Wout,
    int tiles_h, int tiles_w)
{
    int tile_h = (OUT_TILE_H - 1) * strideH + (KH - 1) * dilH + 1;
    int tile_w = (OUT_TILE_W - 1) * strideW + (KW - 1) * dilW + 1;
    extern __shared__ float smem[];
    int input_size = tile_h * tile_w;
    int weight_size = KH * KW;
    int cout_weight_size = COUT_TILE * weight_size;
    float* s_input0 = smem;
    float* s_input1 = smem + input_size;
    float* s_weight0 = smem + 2 * input_size;
    float* s_weight1 = s_weight0 + cout_weight_size;
    float* s_input_buf[2] = { s_input0, s_input1 };
    float* s_weight_buf[2] = { s_weight0, s_weight1 };
    int num_threads = TILE_H * TILE_W;
    int tx = threadIdx.x % TILE_W;
    int ty = threadIdx.x / TILE_W;
    int cout_tiles = (Cout + COUT_TILE - 1) / COUT_TILE;
    long block_idx = blockIdx.x;
    int tile_w_idx = block_idx % tiles_w;
    long tmp = block_idx / tiles_w;
    int tile_h_idx = tmp % tiles_h;
    tmp /= tiles_h;
    int co_tile_idx = tmp % cout_tiles;
    int n = tmp / cout_tiles;
    int co_base = co_tile_idx * COUT_TILE;
    int ho[UNROLL_H];
    int wo[UNROLL_W];
    #pragma unroll
    for (int r = 0; r < UNROLL_H; r++) {
        ho[r] = tile_h_idx * OUT_TILE_H + r * TILE_H + ty;
    }
    #pragma unroll
    for (int c = 0; c < UNROLL_W; c++) {
        wo[c] = tile_w_idx * OUT_TILE_W + c * TILE_W + tx;
    }
    float sums[COUT_TILE][UNROLL_H][UNROLL_W];
    #pragma unroll
    for (int co_off = 0; co_off < COUT_TILE; co_off++) {
        #pragma unroll
        for (int r = 0; r < UNROLL_H; r++) {
            #pragma unroll
            for (int c = 0; c < UNROLL_W; c++) {
                sums[co_off][r][c] = 0.0f;
            }
        }
    }
    int h_in_start = tile_h_idx * OUT_TILE_H * strideH - padH;
    int w_in_start = tile_w_idx * OUT_TILE_W * strideW - padW;
    int total_input = tile_h * tile_w;
    int total_w = weight_size;
    // Preload first channel (ci = 0) into buffer 0, for all co in the tile
    {
        const float* x_base = x + ((long)(n * Cin + 0)) * H * W;
        for (int i = threadIdx.x; i < total_input; i += num_threads) {
            int r = i / tile_w;
            int c = i % tile_w;
            int h_in = h_in_start + r;
            int w_in = w_in_start + c;
            float val = 0.0f;
            if (h_in >= 0 && h_in < H && w_in >= 0 && w_in < W) {
                val = x_base[h_in * W + w_in];
            }
            s_input_buf[0][i] = val;
        }
        for (int co_off = 0; co_off < COUT_TILE; co_off++) {
            int co = co_base + co_off;
            float* s_w_dst = s_weight_buf[0] + co_off * weight_size;
            if (co < Cout) {
                const float* w_base = w + ((long)(co * Cin + 0)) * weight_size;
                for (int i = threadIdx.x; i < total_w; i += num_threads) {
                    s_w_dst[i] = w_base[i];
                }
            } else {
                for (int i = threadIdx.x; i < total_w; i += num_threads) {
                    s_w_dst[i] = 0.0f;
                }
            }
        }
    }
    __syncthreads();
    for (int ci = 0; ci < Cin; ci++) {
        int cur = ci & 1;
        int nxt = (ci + 1) & 1;
        if (ci + 1 < Cin) {
            const float* x_base = x + ((long)(n * Cin + ci + 1)) * H * W;
            for (int i = threadIdx.x; i < total_input; i += num_threads) {
                int r = i / tile_w;
                int c = i % tile_w;
                int h_in = h_in_start + r;
                int w_in = w_in_start + c;
                float val = 0.0f;
                if (h_in >= 0 && h_in < H && w_in >= 0 && w_in < W) {
                    val = x_base[h_in * W + w_in];
                }
                s_input_buf[nxt][i] = val;
            }
            for (int co_off = 0; co_off < COUT_TILE; co_off++) {
                int co = co_base + co_off;
                float* s_w_dst = s_weight_buf[nxt] + co_off * weight_size;
                if (co < Cout) {
                    const float* w_base = w + ((long)(co * Cin + ci + 1)) * weight_size;
                    for (int i = threadIdx.x; i < total_w; i += num_threads) {
                        s_w_dst[i] = w_base[i];
                    }
                } else {
                    for (int i = threadIdx.x; i < total_w; i += num_threads) {
                        s_w_dst[i] = 0.0f;
                    }
                }
            }
        }
        float* s_input = s_input_buf[cur];
        float* s_weight = s_weight_buf[cur];
        int local_h[UNROLL_H];
        int local_w[UNROLL_W];
        #pragma unroll
        for (int r = 0; r < UNROLL_H; r++) {
            local_h[r] = (r * TILE_H + ty) * strideH;
        }
        #pragma unroll
        for (int c = 0; c < UNROLL_W; c++) {
            local_w[c] = (c * TILE_W + tx) * strideW;
        }
        for (int kh = 0; kh < KH; kh++) {
            const float* srow[UNROLL_H];
            #pragma unroll
            for (int r = 0; r < UNROLL_H; r++) {
                int ih = local_h[r] + kh * dilH;
                srow[r] = s_input + ih * tile_w;
            }
            for (int kw = 0; kw < KW; kw++) {
                int iw[UNROLL_W];
                #pragma unroll
                for (int c = 0; c < UNROLL_W; c++) {
                    iw[c] = local_w[c] + kw * dilW;
                }
                float in_vals[UNROLL_H][UNROLL_W];
                #pragma unroll
                for (int r = 0; r < UNROLL_H; r++) {
                    #pragma unroll
                    for (int c = 0; c < UNROLL_W; c++) {
                        in_vals[r][c] = srow[r][iw[c]];
                    }
                }
                #pragma unroll
                for (int co_off = 0; co_off < COUT_TILE; co_off++) {
                    float wv = s_weight[co_off * weight_size + kh * KW + kw];
                    #pragma unroll
                    for (int r = 0; r < UNROLL_H; r++) {
                        #pragma unroll
                        for (int c = 0; c < UNROLL_W; c++) {
                            sums[co_off][r][c] += in_vals[r][c] * wv;
                        }
                    }
                }
            }
        }
        __syncthreads();
    }
    #pragma unroll
    for (int co_off = 0; co_off < COUT_TILE; co_off++) {
        int co = co_base + co_off;
        if (co < Cout) {
            #pragma unroll
            for (int r = 0; r < UNROLL_H; r++) {
                if (ho[r] < Hout) {
                    #pragma unroll
                    for (int c = 0; c < UNROLL_W; c++) {
                        if (wo[c] < Wout) {
                            long out_idx = ((long)(n * Cout + co) * Hout + ho[r]) * Wout + wo[c];
                            out[out_idx] = sums[co_off][r][c];
                        }
                    }
                }
            }
        }
    }
}
torch::Tensor conv2d_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    int strideH, int strideW,
    int padH, int padW,
    int dilH, int dilW)
{
    x = x.contiguous();
    weight = weight.contiguous();
    int N = x.size(0);
    int Cin = x.size(1);
    int H = x.size(2);
    int W = x.size(3);
    int Cout = weight.size(0);
    int KH = weight.size(2);
    int KW = weight.size(3);
    int Hout = (H + 2 * padH - dilH * (KH - 1) - 1) / strideH + 1;
    int Wout = (W + 2 * padW - dilW * (KW - 1) - 1) / strideW + 1;
    auto out = torch::zeros({N, Cout, Hout, Wout}, x.options());
    int tiles_h = (Hout + OUT_TILE_H - 1) / OUT_TILE_H;
    int tiles_w = (Wout + OUT_TILE_W - 1) / OUT_TILE_W;
    int cout_tiles = (Cout + COUT_TILE - 1) / COUT_TILE;
    long total_blocks = (long)N * cout_tiles * tiles_h * tiles_w;
    int threads = TILE_H * TILE_W;
    int tile_h = (OUT_TILE_H - 1) * strideH + (KH - 1) * dilH + 1;
    int tile_w = (OUT_TILE_W - 1) * strideW + (KW - 1) * dilW + 1;
    size_t shared_bytes = (size_t)(2 * tile_h * tile_w + 2 * COUT_TILE * KH * KW) * sizeof(float);
    conv2d_kernel<<<(unsigned int)total_blocks, threads, shared_bytes>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        out.data_ptr<float>(),
        N, Cin, H, W,
        Cout, KH, KW,
        strideH, strideW,
        padH, padW,
        dilH, dilW,
        Hout, Wout,
        tiles_h, tiles_w
    );
    return out;
}
"""

conv2d_cpp_source = r"""
torch::Tensor conv2d_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    int strideH, int strideW,
    int padH, int padW,
    int dilH, int dilW);
"""

conv2d_module = load_inline(
    name="conv2d_module",
    cpp_sources=conv2d_cpp_source,
    cuda_sources=conv2d_source,
    functions=["conv2d_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model using a custom CUDA kernel for 2D convolution
    with square input and asymmetric kernel, dilation, and padding.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: int = 1, padding: tuple = (0, 0), dilation: tuple = (1, 1),
                 bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.use_bias = bias

        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels, kernel_size[0], kernel_size[1])
        )
        nn.init.kaiming_uniform_(self.weight, a=5**0.5)

        if bias:
            self.bias = nn.Parameter(torch.zeros(out_channels))
        else:
            self.register_parameter('bias', None)

        self.conv2d_cuda = conv2d_module.conv2d_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda()
        weight = self.weight.cuda()

        out = self.conv2d_cuda(
            x, weight,
            self.stride, self.stride,
            self.padding[0], self.padding[1],
            self.dilation[0], self.dilation[1]
        )

        if self.bias is not None:
            out = out + self.bias.view(1, -1, 1, 1)

        return out


batch_size = 8
in_channels = 32
out_channels = 64
kernel_size = (5, 9)
width = 512
height = 512
stride = 1
padding = (2, 4)
dilation = (2, 3)


def get_inputs():
    x = torch.rand(batch_size, in_channels, height, width)
    return [x]


def get_init_inputs():
    return [in_channels, out_channels, kernel_size, stride, padding, dilation]

